import { Geist, Geist_Mono } from "next/font/google";
import "./globals.css";

// Fonts configuration
const geistSans = Geist({
  variable: "--font-geist-sans",
  subsets: ["latin"],
});

const geistMono = Geist_Mono({
  variable: "--font-geist-mono",
  subsets: ["latin"],
});

// BMS Website SEO + Social Sharing Metadata
export const metadata = {
  title: {
    default: "BMS - Business Management System",
    template: "%s | BMS",
  },

  description:
    "Smart Business Management, Simplified. Manage products, sales, purchases, customers, suppliers, expenses and reports in one powerful platform.",

  metadataBase: new URL("https://bmstool.vercel.app"),

  openGraph: {
    title: "BMS - Business Management System",
    description:
      "Manage your entire business from one platform with BMS.",
    url: "https://bmstool.vercel.app",
    siteName: "BMS",
    images: [
      {
        url: "/og-image.png",
        width: 1712,
        height: 912,
        alt: "BMS Business Management System",
      },
    ],
    locale: "en_IN",
    type: "website",
  },

  twitter: {
    card: "summary_large_image",
    title: "BMS - Business Management System",
    description:
      "Smart Business Management, Simplified.",
    images: ["/og-image.png"],
  },

  robots: {
    index: true,
    follow: true,
  },
};

// Main Root Layout
export default function RootLayout({ children }) {
  return (
    <html
      lang="en"
      className={`${geistSans.variable} ${geistMono.variable} h-full antialiased`}
    >
      <body className="min-h-full flex flex-col">
        {children}
      </body>
    </html>
  );
}
